//! The Light module of the umbrella crate (design §9.2): `crates/quillshade/src/light/mod.rs`.

use project_core::marker::header;

/// The module's text: the plugin (empty for now) and the error-free environments' paths, `environments` sorted.
pub fn module(environments: &[&str]) -> String {
    let list = if environments.is_empty() {
        "&[]".to_string()
    } else {
        let items: String = environments.iter().map(|p| format!("    {p:?},\n")).collect();
        format!("&[\n{items}]")
    };
    format!(
        "{}\n\
         //! Light domain generated by shader-editor: the environments of `quillshade/light/`.\n\
         \n\
         use bevy::prelude::*;\n\
         \n\
         /// Asset paths of the environments without errors (`outdoor/day`), sorted.\n\
         pub const ENVIRONMENTS: &[&str] = {list};\n\
         \n\
         /// The Light domain's plugin; added by [`crate::QuillshadePlugin`] while the Light domain is enabled.\n\
         pub struct QuillshadeLightInternalPlugin;\n\
         \n\
         impl Plugin for QuillshadeLightInternalPlugin {{\n\
         \x20   fn build(&self, _app: &mut App) {{}}\n\
         }}\n",
        header("//", None)
    )
}
